using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 string selectedTalent="damage";Label careerHud,careerToast;int seenCareerLevel;double careerToastUntil;
 void ShowTalentTree(){var b=Panel("CHARACTER / TALENTS");coopMenu="talents";menu.Position=new(20,25);menu.Size=new(1240,670);b.AddThemeConstantOverride("separation",7);var career=game.Career;
  PackLabel(b,$"CHARACTER LEVEL {career.Level} / 30     •     {career.Points} TALENT POINTS AVAILABLE     •     {career.Spent} INVESTED",19);var bar=new ProgressBar{MaxValue=career.Need,Value=career.Level==30?career.Need:career.Xp,ShowPercentage=false,CustomMinimumSize=new(0,10)};b.AddChild(bar);PackLabel(b,career.Level==30?"MAXIMUM CHARACTER LEVEL":$"{career.Xp:0} / {career.Need:0} MAIN XP / One talent point per level. Earn XP from kills, gathering, crafting, building and discoveries.",12);
  var row=new HBoxContainer();row.AddThemeConstantOverride("separation",20);b.AddChild(row);var canvas=new TalentTreeCanvas{CustomMinimumSize=new(810,425)};row.AddChild(canvas);string[] branches={"Combat","Toughness","Mobility","Survival"};
  for(int column=0;column<4;column++){var label=new Label{Text=branches[column].ToUpperInvariant(),Position=new(15+column*202,9),Size=new(180,22),HorizontalAlignment=HorizontalAlignment.Center};label.AddThemeColorOverride("font_color",new Color(.86f,.74f,.46f));canvas.AddChild(label);}
  foreach(var talent in ExpeditionTalent.All){int column=Array.IndexOf(branches,talent.Branch),rank=career.Rank(talent.Id);string reason=career.Reason(talent);var button=new Godot.Button{Position=new(15+column*202,42+talent.Row*76),Size=new(180,62),ClipContents=true,TooltipText=talent.Description+"\n"+reason,Text=talent.Name+"\n"+$"{rank}/{talent.MaxRank} / LV {talent.Level}"};button.AddThemeFontSizeOverride("font_size",13);button.AddThemeStyleboxOverride("normal",Style(selectedTalent==talent.Id?new(.20f,.27f,.23f):new Color(.07f,.11f,.11f),rank>0?new(.43f,.68f,.40f):reason=="Ready"?new(.84f,.69f,.39f):new Color(.30f,.37f,.33f),selectedTalent==talent.Id?3:1,6));canvas.AddChild(button);button.Pressed+=()=>{selectedTalent=talent.Id;ShowTalentTree();};}
  var node=ExpeditionTalent.All.First(n=>n.Id==selectedTalent);var details=new VBoxContainer{CustomMinimumSize=new(340,0)};row.AddChild(details);PackLabel(details,node.Name.ToUpperInvariant(),22);PackLabel(details,$"{node.Branch} / RANK {career.Rank(node.Id)} OF {node.MaxRank}",13);details.AddChild(new HSeparator());PackLabel(details,node.Description,16);PackLabel(details,$"Requires main level {node.Level}\nOne point per rank.\n"+(node.Row>0?"Previous talent in this branch required.":"Branch entry talent.")+(node.Row==4?"\nSix invested branch points required.":""),13);PackLabel(details,career.Reason(node),14);var learn=new Godot.Button{Text="LEARN / 1 TALENT POINT",Disabled=career.Reason(node)!="Ready",CustomMinimumSize=new(0,40)};details.AddChild(learn);learn.Pressed+=()=>{if(!CoopRequest("talent",node.Id))game.LearnTalent(node.Id);ShowTalentTree();};details.AddChild(new Control{SizeFlagsVertical=Control.SizeFlags.ExpandFill});Button(details,"ACTIVITY SKILLS",ShowSkills);Button(details,"RESET TALENTS / REFUND POINTS",()=>{if(!CoopRequest("talentreset"))game.ResetTalents();ShowTalentTree();});
  PackLabel(b,"Death resets current main XP and activity XP, keeping all earned levels, talents and points.\nMaximum level grants 29 points; the full tree costs 36. Specialize or reset freely while testing. Research points are separate.",12);Button(b,"BACK TO WORLD",CloseMenu);
 }
 void UpdateCareerHud(){if(careerHud==null){careerHud=HudLabel(12);careerToast=HudLabel(20);}var career=game.Career;float width=GetViewport().GetVisibleRect().Size.X;careerHud.Position=new(width-310,26);careerHud.Text=$"CHARACTER LV {career.Level} / {career.Points} TALENT POINTS\n"+(career.Level==30?"MAX LEVEL":$"{career.Xp:0} / {career.Need:0} XP / J TALENTS");if(seenCareerLevel==0)seenCareerLevel=career.Level;if(career.Level>seenCareerLevel){careerToast.Text=$"CHARACTER LEVEL {career.Level}\nTalent point earned / J to spend";careerToastUntil=Time.GetTicksMsec()/1000.0+6;}seenCareerLevel=career.Level;careerToast.Position=new(width-310,108);careerToast.Visible=Time.GetTicksMsec()/1000.0<careerToastUntil;}
 async void CaptureTalentTree(){try{game.Career.Level=14;game.Career.Xp=840;game.Career.Talents.Clear();foreach(string id in new[]{"damage","headshot","reload","health","armor","stamina","sprint","hunger"})game.Career.Learn(id);selectedTalent="melee";ShowTalentTree();await ArtShot("talents-01-character-tree");selectedTalent="resolve";ShowTalentTree();await ArtShot("talents-02-capstone");CloseMenu();UpdateCareerHud();await ArtShot("talents-03-character-hud");GD.Print("PASS / character talent GPU captures");GetTree().Quit();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}}
}
internal partial class TalentTreeCanvas:Control {
 public override void _Draw(){DrawRect(new Rect2(Vector2.Zero,Size),new Color(.045f,.075f,.075f));for(int column=0;column<4;column++)for(int row=0;row<4;row++){float x=105+column*202,y=104+row*76;DrawLine(new(x,y),new(x,y+14),new(.47f,.50f,.37f),2);DrawLine(new(x,y+14),new(x-4,y+9),new(.47f,.50f,.37f),2);DrawLine(new(x,y+14),new(x+4,y+9),new(.47f,.50f,.37f),2);}}
}
